CREATE OR REPLACE FUNCTION public.trailer_placement_rooms() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE asset_key uuid; BEGIN asset_key:=CASE WHEN TG_OP='DELETE' THEN OLD.asset_id ELSE NEW.asset_id END; PERFORM 1 FROM public.assets WHERE id=asset_key FOR UPDATE; IF TG_WHEN='BEFORE' THEN IF TG_OP='DELETE' THEN IF EXISTS(SELECT 1 FROM public.event_bunks b JOIN public.event_bunk_assignments a ON a.bunk_id=b.id WHERE b.placement_id=OLD.id) THEN RAISE EXCEPTION 'Placement has room history; unassign instead of deleting'; END IF; ELSIF NEW.asset_id<>OLD.asset_id OR NEW.event_location_id<>OLD.event_location_id THEN RAISE EXCEPTION 'Move the trailer using a new placement; preserve room history'; ELSIF NEW.end_at IS DISTINCT FROM OLD.end_at THEN IF EXISTS(SELECT 1 FROM public.event_bunks b JOIN public.event_bunk_assignments a ON a.bunk_id=b.id WHERE b.placement_id=OLD.id AND (a.checked_out_at IS NULL OR a.checked_out_at>NEW.end_at)) THEN RAISE EXCEPTION 'Check all trailer occupants out before moving or unassigning; departure must follow their check-outs'; END IF; END IF; ELSE PERFORM public.sync_trailer_rooms(NEW.id); END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.trailer_room_checkin() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE room public.event_bunks; placement public.event_asset_assignments; reassign boolean; BEGIN SELECT * INTO room FROM public.event_bunks WHERE id=NEW.bunk_id; IF room.asset_id IS NULL THEN RETURN NEW; END IF; PERFORM 1 FROM public.assets WHERE id=room.asset_id FOR UPDATE; SELECT * INTO placement FROM public.event_asset_assignments WHERE id=room.placement_id; IF NEW.event_location_id<>placement.event_location_id OR NEW.checked_in_at<placement.start_at OR (placement.end_at IS NOT NULL AND (NEW.checked_out_at IS NULL OR NEW.checked_out_at>placement.end_at)) THEN RAISE EXCEPTION 'Room stay must fall within the trailer location placement'; END IF; reassign:=TG_OP='INSERT'; IF TG_OP='UPDATE' THEN reassign:=NEW.bunk_id<>OLD.bunk_id OR NEW.person_id<>OLD.person_id OR (OLD.checked_out_at IS NOT NULL AND NEW.checked_out_at IS NULL); END IF; IF reassign AND (room.retired OR placement.end_at IS NOT NULL) THEN RAISE EXCEPTION 'Room is no longer available at this location'; END IF; RETURN NEW; END $$;